import {ACOUSTIC_INSTRUMENTS,sampleZones} from './acoustic.js?v=0.14.0';
import {acousticVoice} from './acoustic-audio.js?v=0.14.0';
import {samplerVoice} from './sampler.js?v=0.14.0';

const $=id=>document.getElementById(id);
const rate=44100,length=rate*2;
function metrics(buffer){const data=buffer.getChannelData(0);let energy=0,peak=0,finite=true;for(let i=0;i<data.length;i++){const x=data[i];if(!Number.isFinite(x)){finite=false;continue;}energy+=x*x;peak=Math.max(peak,Math.abs(x));}return {rms:Math.sqrt(energy/data.length),peak,finite};}
function result(name,status,details){const row=document.createElement('tr');for(const value of [name,status,details]){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}row.className=status==='PASS'?'pass':status==='FAIL'?'fail':'warn';$('results').append(row);}
async function sampleFor(type,velocity=.8){const zones=[...new Map([60,64,67].flatMap(note=>sampleZones(type,note,velocity)).map(zone=>[zone.file,zone])).values()];const map=new Map();for(const zone of zones){const url=new URL('./samples/'+zone.file,import.meta.url);const response=await fetch(url,{cache:'default'});if(!response.ok)throw Error(zone.file+' HTTP '+response.status);const bytes=await response.arrayBuffer();const decoder=new OfflineAudioContext(1,rate,rate);const audio=await decoder.decodeAudioData(bytes);if(!audio.length)throw Error(zone.file+' decoded empty');map.set(zone.file,audio);}return map;}
async function renderAcoustic(type,bank,notes=[60],velocity=.8){const ctx=new OfflineAudioContext(1,length,rate);for(const note of notes)acousticVoice(ctx,ctx.destination,type,note,.08,.55,{},velocity,bank);return metrics(await ctx.startRendering());}
async function renderSampler(buffer,notes,velocity=.8){const ctx=new OfflineAudioContext(1,length,rate);for(const note of notes)samplerVoice(ctx,ctx.destination,buffer,note,.08,.55,{mode:'chromatic',root:60},{attack:.003,release:.08,output:-6},velocity);return metrics(await ctx.startRendering());}
function verify(m){return m.finite&&m.rms>0.00002&&m.peak>0.0001&&m.peak<1.5;}
$('run').addEventListener('click',async()=>{const button=$('run');button.disabled=true;$('results').replaceChildren();let pass=0,fail=0,unavailable=0;let firstSample=null;for(const type of Object.keys(ACOUSTIC_INSTRUMENTS)){const name=ACOUSTIC_INSTRUMENTS[type].name;$('summary').textContent='Chargement et rendu : '+name;try{const bank=await sampleFor(type);if(!firstSample)firstSample=bank.values().next().value;const single=await renderAcoustic(type,bank);const chord=await renderAcoustic(type,bank,[60,64,67]);const ok=verify(single)&&verify(chord)&&chord.rms>single.rms*.65;result(name,ok?'PASS':'FAIL','C4 RMS '+single.rms.toFixed(5)+' / accord RMS '+chord.rms.toFixed(5)+' / peak '+chord.peak.toFixed(4));ok?pass++:fail++;}catch(e){result(name,'INDISPONIBLE',e.message);unavailable++;}}
 if(firstSample){for(const [name,notes,velocity] of [['EXO SLICE — C4',[60],.8],['EXO SLICE — accord',[60,64,67],.8],['EXO SLICE — vélocité 0',[60],0]]){try{const m=await renderSampler(firstSample,notes,velocity);const ok=velocity===0?m.peak===0:verify(m);result(name,ok?'PASS':'FAIL','RMS '+m.rms.toFixed(5)+' / peak '+m.peak.toFixed(4));ok?pass++:fail++;}catch(e){result(name,'FAIL',e.message);fail++;}}}else{result('EXO SLICE','INDISPONIBLE','Aucun échantillon acoustique décodé');unavailable++;}
 $('summary').textContent='Terminés : '+pass+' PASS, '+fail+' FAIL, '+unavailable+' INDISPONIBLE. Résultats locaux, non envoyés.';button.disabled=false;});
